  function triggerHealingDragonEndRound(){for(const side of ['p','e']){let u=active(side),foe=opponentActiveOf(u),count=healingDragonCount(u);if(!u||u.curHp<=0||!count)continue;let healed=healUnit(u,Math.round(u.maxHp*.1*count)),drained=0,restored=0;if(foe?.curHp>0)for(let i=0;i<count;i++){let available=foe.moves.filter(move=>move.pp>0);if(!available.length)break;let move=available[Math.floor(Math.random()*available.length)];move.pp--;drained++;let missing=u.moves.filter(own=>own.pp<own.maxPP);if(missing.length){let own=missing[Math.floor(Math.random()*missing.length)];own.pp++;restored++}}game.logs.push(`${u.name} 的 ${count} 條甦醒之龍在回合結束恢復 ${healed} 點體力${drained?`，並從目前場上的對手 ${foe.name} 吸取 ${drained} 點 PP${restored?`、自身恢復 ${restored} 點 PP`:''}`:''}。`)}}

